Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap $imgPath
$w = $bmp.Width; $h = $bmp.Height

function RowStats($bmp, $y, $x0, $x1) {
  $sum=0; $n=0; $dark=0; $mid=0; $red=0
  for ($x=$x0; $x -lt $x1; $x++) {
    $c = $bmp.GetPixel($x,$y)
    $lum = 0.3*$c.R + 0.59*$c.G + 0.11*$c.B
    $sum += $lum; $n++
    if ($c.R -gt 170 -and $c.G -lt 100 -and $c.B -lt 100) { $red++ }
    elseif ($lum -lt 70) { $dark++ }
    elseif ($lum -lt 140) { $mid++ }
  }
  return [pscustomobject]@{ Y=$y; Avg=[math]::Round($sum/$n,1); Dark=$dark; Mid=$mid; Red=$red }
}

