$imgPath = 'C:\Users\trong\.cursor\projects\g-1-1-PROJECT-MAIN-k-s-21\assets\c__Users_trong_AppData_Roaming_Cursor_User_workspaceStorage_e2f419f88c374821257e0056efe34694_images_image-46691c2f-f895-4aee-a2d0-e141dadf6e65.png'
Add-Type -AssemblyName System.Drawing
$bmp = New-Object System.Drawing.Bitmap $imgPath
$w = $bmp.Width; $h = $bmp.Height
Write-Output "Size: $w x $h"

function Band($x0,$x1,$y0,$y1) {
  $darkRows = @(); $darkCols = @()
  for ($y=$y0; $y -le $y1; $y++) {
    $d=0; for ($x=$x0; $x -le $x1; $x++) { $c=$bmp.GetPixel($x,$y); $lum=0.3*$c.R+0.59*$c.G+0.11*$c.B; if($lum -lt 80){$d++} }
    if($d -gt (($x1-$x0+1)*0.08)) { $darkRows += $y }
  }
  for ($x=$x0; $x -le $x1; $x++) {
    $d=0; for ($y=$y0; $y -le $y1; $y++) { $c=$bmp.GetPixel($x,$y); $lum=0.3*$c.R+0.59*$c.G+0.11*$c.B; if($lum -lt 80){$d++} }
    if($d -gt (($y1-$y0+1)*0.08)) { $darkCols += $x }
  }
  $rh = if($darkRows.Count -gt 0){ ($darkRows[-1]-$darkRows[0]+1) } else { 0 }
  $cw = if($darkCols.Count -gt 0){ ($darkCols[-1]-$darkCols[0]+1) } else { 0 }
  return [pscustomobject]@{ Name=$args[0]; Y0=$y0; Y1=$y1; X0=$x0; X1=$x1; RowTop=$darkRows[0]; RowBot=$darkRows[-1]; Height=$rh; ColLeft=$darkCols[0]; ColRight=$darkCols[-1]; Width=$cw }
}

# scan full image rows for text bands
Write-Output "`n=== row bands full width ==="
$bands = @()
$y=0; while($y -lt $h) {
  $d=0; for($x=0;$x -lt $w;$x++){ $c=$bmp.GetPixel($x,$y); if((0.3*$c.R+0.59*$c.G+0.11*$c.B)-lt 85){$d++} }
  if($d -gt ($w*0.05)) { $start=$y; while($y -lt $h){ $d=0; for($x=0;$x -lt $w;$x++){ $c=$bmp.GetPixel($x,$y); if((0.3*$c.R+0.59*$c.G+0.11*$c.B)-lt 85){$d++} }; if($d -le ($w*0.05)){break}; $y++ }; $bands += [pscustomobject]@{Top=$start;Bot=$y-1;H=($y-$start)} }
  $y++
}
$bands | ForEach-Object { "band y=$($_.Top)-$($_.Bot) height=$($_.H)" }

# Gia Lai area lower left-ish
Write-Output "`n=== Gia Lai estimate left area ==="
Band "GiaLai" 0 180 55 95 | Format-List

